ALTER TABLE sys_plan ADD COLUMN migration_enabled boolean NOT NULL DEFAULT true,ADD COLUMN migration_monthly_row_limit int NOT NULL DEFAULT 5000 CHECK(migration_monthly_row_limit BETWEEN 0 AND 1000000);
CREATE TABLE crm_migration_batch(id uuid PRIMARY KEY,tenant_id uuid NOT NULL,member_id uuid NOT NULL,entity_type varchar(30) NOT NULL,file_name varchar(200) NOT NULL,rows_data jsonb NOT NULL,status varchar(20) NOT NULL DEFAULT 'PREVIEW' CHECK(status IN('PREVIEW','COMMITTED')),version bigint NOT NULL DEFAULT 0,results jsonb,created_at timestamptz NOT NULL DEFAULT now(),committed_at timestamptz,UNIQUE(tenant_id,id),FOREIGN KEY(tenant_id,member_id) REFERENCES sys_tenant_member(tenant_id,id));
CREATE TABLE crm_pilot_run(id uuid PRIMARY KEY,tenant_id uuid NOT NULL,actor_member_id uuid NOT NULL,checks jsonb NOT NULL,notes varchar(2000) NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,id),FOREIGN KEY(tenant_id,actor_member_id) REFERENCES sys_tenant_member(tenant_id,id));
DO $$DECLARE n text;BEGIN FOREACH n IN ARRAY ARRAY['crm_migration_batch','crm_pilot_run'] LOOP EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY',n);EXECUTE format('ALTER TABLE %I FORCE ROW LEVEL SECURITY',n);EXECUTE format('CREATE POLICY tenant_boundary ON %I USING(tenant_id=nullif(current_setting(''crm.tenant_id'',true),'''')::uuid) WITH CHECK(tenant_id=nullif(current_setting(''crm.tenant_id'',true),'''')::uuid)',n);END LOOP;END$$;
GRANT SELECT,INSERT,UPDATE ON crm_migration_batch TO crm_runtime;
GRANT SELECT,INSERT ON crm_pilot_run TO crm_runtime;
